scriptTask.script:
def cantidad = execution.getVariable("recordatorios")

if (cantidad == null) {
    cantidad = 0
}

execution.setVariable("recordatorios", cantidad + 1)

def runtimeService = org.flowable.engine.impl.context.Context .getProcessEngineConfiguration() .getRuntimeService()
def repositoryService = org.flowable.engine.impl.context.Context .getProcessEngineConfiguration() .getRepositoryService()
def processDefinitionKey = repositoryService .getProcessDefinition(execution.getProcessDefinitionId()) .getKey()
def cantidad = runtimeService .createProcessInstanceQuery() .processDefinitionKey(processDefinitionKey) .active() .list() .findAll { instancia -> instancia.getId() != execution.getProcessInstanceId() } .size()
execution.setVariable("cantidadCursosActivos", cantidad)
